type ProductCategory = "Blended Masala" | "Whole Spices" | "Chilli Powders" | "Turmeric" | "Gift Packs" | "Printed T-Shirts";
type AdminProduct = { id: number; name: string; description: string; category: ProductCategory; price: number; mrp: number; rating: number; reviews: number; image: string; badge: string | null; stock: number; active: number; costPerItem?: number; sku?: string; barcode?: string; trackQuantity?: number; lowStockThreshold?: number; seoTitle?: string; seoDescription?: string; slug?: string; variants?: string };
type AdminOrder = { id: number; customerName: string; phone: string; email: string; address: string; items: string; subtotal: number; shippingFee: number; discount: number; total: number; paymentStatus: string; orderStatus: string; createdAt: string; courier?: string; trackingNumber?: string };
type AdminCustomer = { email: string; name: string; phone: string; address: string; orderCount: number; totalSpent: number; lastOrderAt: string };
type AdminDiscount = { id: number; code: string; type: "percentage" | "fixed"; value: number; minimumPurchase: number; usageLimit: number | null; usageCount: number; startsAt: string; endsAt: string; active: number };
type AdminSettings = { storeName: string; supportPhone: string; lowStockThreshold: number; announcement: string; storeEmail?: string; currency?: string; timezone?: string; codEnabled?: number; codMinOrder?: number; codMaxOrder?: number };
type Icon = ComponentType<{ className?: string }>;

function store(context: Route.LoaderArgs["context"]) {
  const namespace = context.cloudflare.env.ITEMS;
  return namespace.get(namespace.idFromName("default"));
}

export async function loader({ request, context }: Route.LoaderArgs) {
  const env = context.cloudflare.env;
  const authenticated = await hasAdminSession(request, env);
  if (!authenticated) return { authenticated: false as const, setupRequired: !env.ADMIN_ACCESS_KEY, twoFactorConfigured: Boolean(env.ADMIN_TOTP_SECRET) };
  const items = store(context);
  const [dashboard, products, orders, pendingApprovals, expenses, settings, customers, discounts] = await Promise.all([items.getDashboard(), items.listProducts(true), items.listOrders(), items.listPendingApprovals(), items.listExpenses(), items.getSettings(), items.listCustomers(), items.listDiscounts()]);
  return { authenticated: true as const, dashboard, products, orders, pendingApprovals, expenses, settings, customers, discounts, twoFactorConfigured: Boolean(env.ADMIN_TOTP_SECRET) };
}

export async function action({ request, context }: Route.ActionArgs) {
  if (!isSameOrigin(request)) return { ok: false, message: "Request blocked: origin validation failed." };
  const form = await request.formData();
  const intent = String(form.get("intent") ?? "");
  const env = context.cloudflare.env;

  if (intent === "login") {
    const result = await verifyAdminLogin(String(form.get("accessKey") ?? ""), String(form.get("otp") ?? ""), env);
    if (!result.ok) return { ok: false, message: result.reason === "setup-required" ? "Admin setup is incomplete. Configure ADMIN_ACCESS_KEY before signing in." : result.reason === "invalid-otp" ? "The verification code is invalid or expired." : "The access key is invalid." };
    return redirect("/admin", { headers: { "Set-Cookie": sessionCookie(await createAdminSession(env)) } });
  }
  if (intent === "logout") return redirect("/admin", { headers: { "Set-Cookie": clearSessionCookie() } });
  if (!(await hasAdminSession(request, env))) return { ok: false, message: "Your admin session expired. Sign in again." };

  const items = store(context);
  try {
    if (intent === "update-product") {
      const id = Number(form.get("id"));
      const name = String(form.get("name") ?? "").trim().slice(0, 120);
      const description = String(form.get("description") ?? "").trim().slice(0, 300);
      const category = String(form.get("category") ?? "Blended Masala") as ProductCategory;
      const image = String(form.get("image") ?? "").trim().slice(0, 500);
      const price = Number(form.get("price"));
      const mrp = Number(form.get("mrp"));
      const stock = Number(form.get("stock"));
      const costPerItem = Number(form.get("costPerItem") ?? 0);
      const variants = String(form.get("variants") ?? "[]").trim() || "[]";
      JSON.parse(variants);
      if (!Number.isInteger(id) || !name || !description || !/^https:\/\//i.test(image) || !Number.isFinite(price) || price < 0 || !Number.isFinite(mrp) || mrp < price || !Number.isInteger(stock) || stock < 0 || costPerItem < 0) return { ok: false, message: "Check the product, image, inventory and pricing values." };
      await items.updateProduct(id, { name, description, category, image, price, mrp, stock, costPerItem, sku: String(form.get("sku") ?? "").trim().slice(0, 80), barcode: String(form.get("barcode") ?? "").trim().slice(0, 80), trackQuantity: form.get("trackQuantity") === "on" ? 1 : 0, lowStockThreshold: Number(form.get("lowStockThreshold") ?? 10), seoTitle: String(form.get("seoTitle") ?? "").trim().slice(0, 160), seoDescription: String(form.get("seoDescription") ?? "").trim().slice(0, 300), slug: String(form.get("slug") ?? "").trim().slice(0, 120), variants, badge: String(form.get("badge") ?? "").trim().slice(0, 40) || null, active: form.get("active") === "on" ? 1 : 0 });
      return { ok: true, message: `${name} saved.` };
    }

    if (intent === "bulk-product") {
      const ids = form.getAll("productId").map(Number).filter((id) => Number.isInteger(id) && id > 0);
      const mode = String(form.get("bulkMode") ?? "");
      if (!ids.length) return { ok: false, message: "Select at least one product first." };
      for (const id of ids) {
        if (mode === "activate") await items.updateProduct(id, { active: 1 });
        if (mode === "draft") await items.updateProduct(id, { active: 0 });
        if (mode === "stock") await items.updateProduct(id, { stock: Math.max(0, Number(form.get("bulkStock") ?? 0)) });
        if (mode === "price") await items.updateProduct(id, { price: Math.max(0, Number(form.get("bulkPrice") ?? 0)) });
      }
      return { ok: true, message: `${ids.length} product${ids.length === 1 ? "" : "s"} updated.` };
    }

    if (intent === "add-product") {
      const name = String(form.get("name") ?? "").trim().slice(0, 120);
      const description = String(form.get("description") ?? "").trim().slice(0, 300);
      const category = String(form.get("category") ?? "Blended Masala") as ProductCategory;
      const image = String(form.get("image") ?? "").trim().slice(0, 500);
      const price = Number(form.get("price"));
      const mrp = Number(form.get("mrp"));
      const stock = Number(form.get("stock"));
      if (!name || !description || !/^https:\/\//i.test(image) || !Number.isFinite(price) || !Number.isFinite(mrp) || mrp < price || !Number.isInteger(stock) || stock < 0) return { ok: false, message: "Complete the product fields with valid values." };
      await items.createProduct({ name, description, category, price, mrp, image, badge: String(form.get("badge") ?? "").trim() || null, stock, costPerItem: Number(form.get("costPerItem") ?? 0), sku: String(form.get("sku") ?? "").trim(), lowStockThreshold: Number(form.get("lowStockThreshold") ?? 10), variants: String(form.get("variants") ?? "[]") });
      return { ok: true, message: `${name} added to your catalogue.` };
    }

    if (intent === "approve-order") { const order = await items.approveOrder(Number(form.get("id"))); return { ok: true, message: `Order #${order.id} approved.` }; }
    if (intent === "reject-order") { await items.rejectOrder(Number(form.get("id"))); return { ok: true, message: `Order #${Number(form.get("id"))} rejected and inventory restored.` }; }
    if (intent === "cancel-order") { await items.cancelOrder(Number(form.get("id"))); return { ok: true, message: `Order #${Number(form.get("id"))} cancelled and inventory restored.` }; }
    if (intent === "fulfillment") {
      const id = Number(form.get("id"));
      const status = String(form.get("orderStatus")) as "Pending" | "Packed" | "Dispatched" | "Delivered";
      if (!["Pending", "Packed", "Dispatched", "Delivered"].includes(status)) return { ok: false, message: "Invalid fulfilment status." };
      await items.updateFulfillment(id, status, String(form.get("courier") ?? ""), String(form.get("trackingNumber") ?? ""));
      return { ok: true, message: `Order #${id} marked ${status.toLowerCase()}.` };
    }

    if (intent === "create-discount") {
      const code = String(form.get("code") ?? "").trim().toUpperCase().replace(/[^A-Z0-9_-]/g, "");
      const type = String(form.get("type") ?? "percentage") as "percentage" | "fixed";
      const value = Number(form.get("value"));
      const minimumPurchase = Number(form.get("minimumPurchase") ?? 0);
      const usageLimitRaw = String(form.get("usageLimit") ?? "").trim();
      const usageLimit = usageLimitRaw ? Number(usageLimitRaw) : null;
      const startsAt = String(form.get("startsAt") ?? new Date().toISOString()).slice(0, 40);
      const endsAt = String(form.get("endsAt") ?? new Date(Date.now() + 30 * 86400000).toISOString()).slice(0, 40);
      if (!code || !["percentage", "fixed"].includes(type) || !Number.isFinite(value) || value <= 0 || (type === "percentage" && value > 100) || minimumPurchase < 0 || (usageLimit !== null && (!Number.isInteger(usageLimit) || usageLimit < 1))) return { ok: false, message: "Enter valid discount rules." };
      await items.createDiscount({ code, type, value, minimumPurchase, usageLimit, startsAt, endsAt, active: 1 });
      return { ok: true, message: `${code} discount created.` };
    }
    if (intent === "delete-discount") { await items.deleteDiscount(Number(form.get("id"))); return { ok: true, message: "Discount deleted." }; }
    if (intent === "settings") {
      await items.updateSettings({ storeName: String(form.get("storeName") ?? "Cool Masala").trim().slice(0, 80), storeEmail: String(form.get("storeEmail") ?? "").trim().slice(0, 160), supportPhone: String(form.get("supportPhone") ?? "").trim().slice(0, 30), currency: String(form.get("currency") ?? "INR").slice(0, 10), timezone: String(form.get("timezone") ?? "Asia/Kolkata").slice(0, 60), lowStockThreshold: Math.max(0, Number(form.get("lowStockThreshold") ?? 10)), announcement: String(form.get("announcement") ?? "").trim().slice(0, 160), codEnabled: form.get("codEnabled") === "on" ? 1 : 0, codMinOrder: Math.max(0, Number(form.get("codMinOrder") ?? 0)), codMaxOrder: Math.max(0, Number(form.get("codMaxOrder") ?? 100000)) });
      return { ok: true, message: "Store settings saved." };
    }
    return { ok: false, message: "Unknown admin action." };
  } catch (error) {
    return { ok: false, message: error instanceof Error ? error.message : "The action could not be completed." };
  }
}

