        <div className="flex-1 overflow-y-auto p-3"><p className={(collapsed ? "lg:hidden " : "") + "admin-sidebar-label px-3 pb-3 pt-2 text-[10px] font-bold uppercase tracking-[.16em] text-[#8c9196]"}>Store management</p>{navItems.map((item, index) => { const IconComponent = item.icon; return <div key={item.id}>{item.group && <p className={(collapsed ? "lg:hidden " : "") + "px-3 pb-3 pt-6 text-[10px] font-bold uppercase tracking-[.16em] text-[#8c9196]"}>{item.group}</p>}<button type="button" onClick={() => goTo(item.id)} title={collapsed ? item.label : undefined} className={(section === item.id ? "admin-nav-active bg-[#e3f1ed] text-[#006e52] " : "text-[#4d5156] hover:bg-[#f6f6f7] ") + "mb-1 flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-semibold transition"}><IconComponent className="size-[18px] shrink-0" /><span className={(collapsed ? "lg:hidden " : "") + "flex-1 text-left"}>{item.label}</span>{item.countKey === "orders" && pendingApprovals.length > 0 && <span className="rounded-full bg-[#f1c232] px-2 py-0.5 text-[10px] font-bold text-[#202223]">{pendingApprovals.length}</span>}{item.id === "analytics" && <span className={(collapsed ? "lg:hidden " : "") + "rounded bg-[#f1f2f3] px-1.5 py-0.5 text-[9px] font-bold uppercase text-[#8c9196]"}>Soon</span>}</button>{index === 5 && <div className="my-4 border-t border-[#e1e3e5]" />}</div>; })}<Link to="/admin/health" className={(collapsed ? "lg:justify-center " : "") + "mt-2 flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-semibold text-[#4d5156] hover:bg-[#f6f6f7]"}><Activity className="size-[18px] shrink-0" /><span className={collapsed ? "lg:hidden" : ""}>System health</span></Link></div>
